 fs::path root=argc>1?argv[1]:"projects/retarget_lab";fs::path results=argc>2?argv[2]:".cache/m74/lab-checks.json";auto roles=Read(root/"Authoring"/"roles.json");std::string error;
 ModelImportSettings sourceSettings;ModelImportReport sourceReport;MeshData source;Check(ImportMotionSource((root/"Sources"/"source.gltf").string(),sourceSettings,source,sourceReport,error),"original multi-part source enters normal M66 glTF boundary");if(!source.skeletal)throw std::runtime_error(error);
 const auto& sourceRig=source.skeletal->skeleton;Check(sourceRig.names.size()>64&&source.skeletal->clips.size()==3,"source retains full helpers and three reusable performances");Json observations=Json::array();double angularError=0,positionError=0,restOffsetError=0,rootError=0,previewError=0;
 // Tolerances are fixed in advance: 2e-5 radians, 20 micrometres for direct
