  auto expectedTurn=profile.modelAlignment*glm::angleAxis(.8f,glm::vec3(0,1,0))*glm::inverse(profile.modelAlignment)*Rotation(referenceGlobal[pivot]);double turnError=Angle(Rotation(travelGlobal[pivot]),expectedTurn);angularError=std::max(angularError,turnError);Check(turnError<2e-5,"root turning retains independent 0.8-radian source rotation in the declared alignment frame");
  auto& extracted=Clip(cooked,"TravelExtract");auto& inPlace=Clip(cooked,"TravelInPlace");auto& preserve=Clip(cooked,"TravelPreserve");double reconstruction=0,inPlaceDifference=0;
