  rootError=std::max(rootError,reconstruction);Check(reconstruction<.0002&&inPlaceDifference<2e-5,"ordinary extracted track reconstructs locomotion once and in-place retains the identical complementary pose");Check(inPlace.motion.empty()&&!extracted.motion.empty(),"in-place discards only declared motion track while extraction stays queryable");
