 Json result={{"checks",checks},{"failures",failures},{"angularErrorRadians",angularError},{"positionErrorMetres",positionError},{"restOffsetErrorMetres",restOffsetError},{"rootReconstructionMatrixError",rootError},{"previewBakePositionErrorMetres",previewError},{"conditions",observations}};fs::create_directories(results.parent_path());std::ofstream(results)<<result.dump(2)<<'\n';std::cout<<result.dump(2)<<'\n';return failures?1:0;
